__hydrateVak("vmbo","gs",{"A":{"sv":[{"v":"Wat zijn normen?","o":["Regels voor je gedrag","Wat je belangrijk vindt","Een geloof","Een traditie"],"c":0,"d":1,"u":"Normen zijn gedragsregels.","uo":["Klopt: normen zijn gedragsregels.","Dat zijn waarden.","Nee, het juiste antwoord is «Regels voor je gedrag».","Nee, het juiste antwoord is «Regels voor je gedrag»."],"uh":"Regels voor je gedrag: Normen zijn gedragsregels."},{"v":"Wat zijn waarden?","o":["Gedragsregels","Wat je belangrijk vindt","Een gebouw","Een wet"],"c":1,"d":1,"u":"Wat mensen belangrijk vinden.","uo":["Dat zijn normen.","Klopt: wat mensen belangrijk vinden.","Nee, het juiste antwoord is «Wat je belangrijk vindt».","Nee, het juiste antwoord is «Wat je belangrijk vindt»."],"uh":"Wat je belangrijk vindt: Wat mensen belangrijk vinden."},{"v":"Wat betekent secularisatie?","o":["Meer regels","Religie wordt belangrijker","Religie wordt minder belangrijk","Meer tradities"],"c":2,"d":2,"u":"Het geloof wordt minder bepalend.","uo":["Nee, het juiste antwoord is «Religie wordt minder belangrijk».","Juist andersom.","Klopt: het geloof wordt minder bepalend.","Nee, het juiste antwoord is «Religie wordt minder belangrijk»."],"uh":"Religie wordt minder belangrijk: Het geloof wordt minder bepalend."},{"v":"Wat is een traditie?","o":["Een wet","Een geloof","Een mening vooraf","Een overgeleverde gewoonte"],"c":3,"d":1,"u":"Een gewoonte die van generatie op generatie overgaat.","uo":["Nee, het juiste antwoord is «Een overgeleverde gewoonte».","Nee, het juiste antwoord is «Een overgeleverde gewoonte».","Dat is een vooroordeel.","Klopt: een gewoonte die van generatie op generatie overgaat."],"uh":"Een overgeleverde gewoonte: Een gewoonte die van generatie op generatie overgaat."},{"v":"Wat is een vooroordeel?","o":["Een oordeel zonder de feiten","Een gedragsregel","Een traditie","Een geloof"],"c":0,"d":2,"u":"Een mening vooraf, zonder de feiten.","uo":["Klopt: een mening vooraf, zonder de feiten.","Nee, het juiste antwoord is «Een oordeel zonder de feiten».","Nee, het juiste antwoord is «Een oordeel zonder de feiten».","Nee, het juiste antwoord is «Een oordeel zonder de feiten»."],"uh":"Een oordeel zonder de feiten: Een mening vooraf, zonder de feiten."},{"v":"Wat is tolerantie?","o":["Anderen uitsluiten","Andere meningen verdragen","Regels opleggen","Een traditie"],"c":1,"d":2,"u":"Andere meningen en geloven verdragen.","uo":["Juist niet, het juiste antwoord is «Andere meningen verdragen».","Klopt: andere meningen en geloven verdragen.","Nee, het juiste antwoord is «Andere meningen verdragen».","Nee, het juiste antwoord is «Andere meningen verdragen»."],"uh":"Andere meningen en geloven verdragen."},{"v":"Wat is een standensamenleving?","o":["Een democratie","Een gelijke samenleving","Een samenleving met vaste lagen","Een dictatuur"],"c":2,"d":2,"u":"Vaste maatschappelijke lagen.","uo":["Nee, het juiste antwoord is «Een samenleving met vaste lagen».","Juist niet gelijk.","Klopt: vaste maatschappelijke lagen.","Nee, het juiste antwoord is «Een samenleving met vaste lagen»."],"uh":"Een samenleving met vaste lagen: Vaste maatschappelijke lagen."},{"v":"Wat is mentaliteit?","o":["Een gebouw","Een wet","Een geloof","De manier van denken in een tijd"],"c":3,"d":2,"u":"Hoe mensen in een tijd denken.","uo":["Nee, het juiste antwoord is «De manier van denken in een tijd».","Nee, het juiste antwoord is «De manier van denken in een tijd».","Nee, het juiste antwoord is «De manier van denken in een tijd».","Klopt: hoe mensen in een tijd denken."],"uh":"De manier van denken in een tijd: Hoe mensen in een tijd denken."},{"v":"Wat is emancipatie?","o":["Streven naar gelijke rechten","Minder rechten","Meer regels","Een traditie"],"c":0,"d":2,"u":"Streven naar gelijke rechten.","uo":["Klopt: streven naar gelijke rechten.","Juist meer, het juiste antwoord is «Streven naar gelijke rechten».","Nee, het juiste antwoord is «Streven naar gelijke rechten».","Nee, het juiste antwoord is «Streven naar gelijke rechten»."],"uh":"Streven naar gelijke rechten."},{"v":"Wat hoort bij cultuur?","o":["Alleen het weer","Gewoonten en gebruiken","Alleen de economie","Alleen de wet"],"c":1,"d":1,"u":"Gewoonten, taal en gebruiken van een groep.","uo":["Nee, het juiste antwoord is «Gewoonten en gebruiken».","Klopt: gewoonten, taal en gebruiken van een groep.","Nee, het juiste antwoord is «Gewoonten en gebruiken».","Nee, het juiste antwoord is «Gewoonten en gebruiken»."],"uh":"Gewoonten en gebruiken: Gewoonten, taal en gebruiken van een groep."},{"v":"Waarom werd Nederland minder religieus?","o":["Door meer regels","Door meer kerken","Door secularisatie","Door tradities"],"c":2,"d":3,"u":"Door secularisatie werd geloof minder belangrijk.","uo":["Nee, het juiste antwoord is «Door secularisatie».","Juist andersom.","Klopt: door secularisatie werd geloof minder belangrijk.","Nee, het juiste antwoord is «Door secularisatie»."],"uh":"Door secularisatie werd geloof minder belangrijk."}],"begrippen":[{"t":"Cultuur","d":"de gewoonten, gebruiken en waarden van een groep"},{"t":"Mentaliteit","d":"de manier van denken van mensen in een bepaalde tijd"},{"t":"Waarden","d":"wat mensen belangrijk en nastrevenswaardig vinden"},{"t":"Normen","d":"regels over hoe je je hoort te gedragen"},{"t":"Religie","d":"een geloof met eigen regels en rituelen"},{"t":"Traditie","d":"een gewoonte die van generatie op generatie overgaat"},{"t":"Secularisatie","d":"het minder belangrijk worden van religie"},{"t":"Tolerantie","d":"het verdragen van andere meningen en geloven"},{"t":"Standensamenleving","d":"een samenleving met vaste maatschappelijke lagen"},{"t":"Emancipatie","d":"het streven naar gelijke rechten en kansen"},{"t":"Vooroordeel","d":"een mening vooraf, zonder de feiten te kennen"},{"t":"Identiteit","d":"het gevoel bij een groep of gebied te horen"}],"sam":"<div class=\"sam-intro\"><strong>Cultuur</strong> is het geheel van gewoonten, waarden en gebruiken van een groep; de <strong>mentaliteit</strong> is de manier van denken in een tijd. Door <strong>secularisatie</strong> werd religie in Nederland minder bepalend.</div><div class=\"sam-head\">1. Cultuur, waarden en normen</div><p><strong>Cultuur</strong> omvat de gewoonten, gebruiken en waarden van een groep, terwijl de <strong>mentaliteit</strong> gaat over de manier van denken in een bepaalde tijd. <strong>Waarden</strong> zijn wat mensen belangrijk vinden (bijvoorbeeld vrijheid); <strong>normen</strong> zijn de gedragsregels die daaruit volgen. Een <strong>traditie</strong> is een gewoonte die van generatie op generatie overgaat.</p><div class=\"sam-head\">2. Religie en verandering</div><p>Lange tijd bepaalde <strong>religie</strong> het dagelijks leven. Door <strong>secularisatie</strong> werd het geloof minder belangrijk. In een vroegere <strong>standensamenleving</strong> lag je plaats vast; door <strong>emancipatie</strong> streden groepen voor gelijke rechten. <strong>Tolerantie</strong> betekent andere meningen verdragen, terwijl een <strong>vooroordeel</strong> juist een oordeel vooraf is.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Cultuur</div><div class=\"sam-definitie-body\">de gewoonten, gebruiken en waarden van een groep.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Mentaliteit</div><div class=\"sam-definitie-body\">de manier van denken van mensen in een bepaalde tijd.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Waarden</div><div class=\"sam-definitie-body\">wat mensen belangrijk en nastrevenswaardig vinden.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Normen</div><div class=\"sam-definitie-body\">regels over hoe je je hoort te gedragen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Religie</div><div class=\"sam-definitie-body\">een geloof met eigen regels en rituelen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Traditie</div><div class=\"sam-definitie-body\">een gewoonte die van generatie op generatie overgaat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Secularisatie</div><div class=\"sam-definitie-body\">het minder belangrijk worden van religie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Tolerantie</div><div class=\"sam-definitie-body\">het verdragen van andere meningen en geloven.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Standensamenleving</div><div class=\"sam-definitie-body\">een samenleving met vaste maatschappelijke lagen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Emancipatie</div><div class=\"sam-definitie-body\">het streven naar gelijke rechten en kansen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vooroordeel</div><div class=\"sam-definitie-body\">een mening vooraf, zonder de feiten te kennen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Identiteit</div><div class=\"sam-definitie-body\">het gevoel bij een groep of gebied te horen.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Cultuur»</b> is gewoonten en waarden, terwijl <b>«Mentaliteit»</b> manier van denken is. <b>«Waarden»</b> is wat men belangrijk vindt, terwijl <b>«Normen»</b> gedragsregels is. <b>«Religie»</b> is een geloof, terwijl <b>«Traditie»</b> overgeleverde gewoonte is. <b>«Secularisatie»</b> is religie wordt minder, terwijl <b>«Emancipatie»</b> streven naar gelijkheid is.</div>"},"B":{"sv":[{"v":"Wat is de Grondwet?","o":["De belangrijkste wet","Een gewone wet","Een verdrag","Een advies"],"c":0,"d":1,"u":"De belangrijkste wet met de regels van de staat.","uo":["Klopt: de belangrijkste wet met de regels van de staat.","Nee, de hoogste.","Nee, het juiste antwoord is «De belangrijkste wet».","Nee, het juiste antwoord is «De belangrijkste wet»."],"uh":"De belangrijkste wet met de regels van de staat."},{"v":"Wat is een grondrecht?","o":["Een plicht","Een recht voor iedereen","Een belasting","Een straf"],"c":1,"d":2,"u":"Een recht dat iedereen heeft, zoals vrije meningsuiting.","uo":["Nee, het juiste antwoord is «Een recht voor iedereen».","Klopt: een recht dat iedereen heeft, zoals vrije meningsuiting.","Nee, het juiste antwoord is «Een recht voor iedereen».","Nee, het juiste antwoord is «Een recht voor iedereen»."],"uh":"Een recht dat iedereen heeft, zoals vrije meningsuiting."},{"v":"Wat regelt de Trias Politica?","o":["De euro","De belasting","De scheiding van machten","Het leger"],"c":2,"d":2,"u":"Wetgevende, uitvoerende en rechterlijke macht apart.","uo":["Nee, het juiste antwoord is «De scheiding van machten».","Nee, het juiste antwoord is «De scheiding van machten».","Klopt: wetgevende, uitvoerende en rechterlijke macht apart.","Nee, het juiste antwoord is «De scheiding van machten»."],"uh":"De scheiding van machten: Wetgevende, uitvoerende en rechterlijke macht apart."},{"v":"Wie maakt de wetten?","o":["De rechter","De koning alleen","De politie","De wetgevende macht"],"c":3,"d":2,"u":"De wetgevende macht maakt wetten.","uo":["De rechter spreekt recht.","Niet alleen.","Nee, het juiste antwoord is «De wetgevende macht».","Klopt: de wetgevende macht maakt wetten."],"uh":"De wetgevende macht maakt wetten."},{"v":"Wie voert de wetten uit?","o":["De uitvoerende macht","De rechterlijke macht","Alleen de burgers","De Eerste Kamer"],"c":0,"d":2,"u":"De regering voert wetten uit.","uo":["Klopt: de regering voert wetten uit.","Die spreekt recht.","Nee, het juiste antwoord is «De uitvoerende macht».","Die keurt goed of af."],"uh":"De uitvoerende macht: De regering voert wetten uit."},{"v":"Wie spreekt recht?","o":["De regering","De rechterlijke macht","Het parlement","De koning"],"c":1,"d":2,"u":"De rechters spreken recht.","uo":["Die voert uit.","Klopt: de rechters spreken recht.","Dat controleert.","Nee, het juiste antwoord is «De rechterlijke macht»."],"uh":"De rechters spreken recht."},{"v":"Wat is de Tweede Kamer?","o":["De rechtbank","De regering","De gekozen volksvertegenwoordiging","De koning"],"c":2,"d":2,"u":"Gekozen, maakt en controleert wetten.","uo":["Nee, het juiste antwoord is «De gekozen volksvertegenwoordiging».","Dat is iets anders.","Klopt: gekozen, maakt en controleert wetten.","Nee, het juiste antwoord is «De gekozen volksvertegenwoordiging»."],"uh":"De gekozen volksvertegenwoordiging: Gekozen, maakt en controleert wetten."},{"v":"Wat doet de Eerste Kamer?","o":["Wetten maken","Recht spreken","Belasting innen","Wetten goed- of afkeuren"],"c":3,"d":2,"u":"De Eerste Kamer keurt wetten goed of af.","uo":["Dat doet vooral de Tweede Kamer.","Nee, het juiste antwoord is «Wetten goed- of afkeuren».","Nee, het juiste antwoord is «Wetten goed- of afkeuren».","Klopt: de Eerste Kamer keurt wetten goed of af."],"uh":"Wetten goed- of afkeuren: De Eerste Kamer keurt wetten goed of af."},{"v":"Wat is een democratie?","o":["Het volk kiest","Eén persoon beslist","Er zijn geen regels","De koning beslist alles"],"c":0,"d":1,"u":"Het volk kiest zijn vertegenwoordigers.","uo":["Klopt: het volk kiest zijn vertegenwoordigers.","Dat is een dictatuur.","Nee, het juiste antwoord is «Het volk kiest».","Nee, het juiste antwoord is «Het volk kiest»."],"uh":"Het volk kiest zijn vertegenwoordigers."},{"v":"Wie horen bij de regering?","o":["De rechters","De koning en ministers","De burgers","De Tweede Kamer"],"c":1,"d":2,"u":"De koning en de ministers samen.","uo":["Nee, het juiste antwoord is «De koning en ministers».","Klopt: de koning en de ministers samen.","Nee, het juiste antwoord is «De koning en ministers».","Die controleert de regering."],"uh":"De koning en de ministers samen."},{"v":"Waarom is de macht verdeeld in drieën?","o":["Om oorlog te voeren","Om belasting te innen","Om machtsmisbruik te voorkomen","Om geld te sparen"],"c":2,"d":3,"u":"Zo controleren de machten elkaar.","uo":["Nee, het juiste antwoord is «Om machtsmisbruik te voorkomen».","Nee, het juiste antwoord is «Om machtsmisbruik te voorkomen».","Klopt: zo controleren de machten elkaar.","Nee, het juiste antwoord is «Om machtsmisbruik te voorkomen»."],"uh":"Om machtsmisbruik te voorkomen: Zo controleren de machten elkaar."}],"begrippen":[{"t":"Grondwet","d":"de belangrijkste wet met de regels van de staat"},{"t":"Grondrecht","d":"een recht dat iedereen heeft, zoals vrijheid van meningsuiting"},{"t":"Trias Politica","d":"de scheiding in wetgevende, uitvoerende en rechterlijke macht"},{"t":"Wetgevende macht","d":"de macht die wetten maakt"},{"t":"Uitvoerende macht","d":"de macht die de wetten uitvoert, de regering"},{"t":"Rechterlijke macht","d":"de macht die recht spreekt, de rechters"},{"t":"Regering","d":"de koning en de ministers samen"},{"t":"Parlement","d":"de volksvertegenwoordiging: de Eerste en Tweede Kamer"},{"t":"Tweede Kamer","d":"de gekozen Kamer die wetten maakt en de regering controleert"},{"t":"Eerste Kamer","d":"de Kamer die wetsvoorstellen goed- of afkeurt"},{"t":"Democratie","d":"een bestuur waarin het volk zijn vertegenwoordigers kiest"},{"t":"Verzorgingsstaat","d":"een staat die zorgt voor het welzijn van de burgers"}],"sam":"<div class=\"sam-intro\">De <strong>Grondwet</strong> bevat de belangrijkste regels en de <strong>grondrechten</strong>. De <strong>Trias Politica</strong> verdeelt de macht in drieën. Het <strong>parlement</strong> controleert de <strong>regering</strong>.</div><div class=\"sam-head\">1. De Grondwet en grondrechten</div><p>De <strong>Grondwet</strong> is de belangrijkste wet: alle andere wetten moeten eraan voldoen. Erin staan de <strong>grondrechten</strong>, zoals vrijheid van meningsuiting en het recht op gelijke behandeling. Nederland is een <strong>democratie</strong>: het volk kiest zijn vertegenwoordigers.</p><div class=\"sam-head\">2. De Trias Politica</div><p>Om machtsmisbruik te voorkomen is de macht verdeeld (de <strong>Trias Politica</strong>): de <strong>wetgevende macht</strong> maakt wetten, de <strong>uitvoerende macht</strong> voert ze uit en de <strong>rechterlijke macht</strong> spreekt recht. Zo controleren de machten elkaar.</p><div class=\"sam-head\">3. Regering en parlement</div><p>De <strong>regering</strong> (de koning en de ministers) bestuurt het land. Het <strong>parlement</strong>, bestaande uit de <strong>Tweede Kamer</strong> (gekozen, maakt en controleert wetten) en de <strong>Eerste Kamer</strong> (keurt wetten goed of af), controleert de regering. Samen zorgen ze onder meer voor de <strong>verzorgingsstaat</strong>.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Grondwet</div><div class=\"sam-definitie-body\">de belangrijkste wet met de regels van de staat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Grondrecht</div><div class=\"sam-definitie-body\">een recht dat iedereen heeft, zoals vrijheid van meningsuiting.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Trias Politica</div><div class=\"sam-definitie-body\">de scheiding in wetgevende, uitvoerende en rechterlijke macht.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Wetgevende macht</div><div class=\"sam-definitie-body\">de macht die wetten maakt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Uitvoerende macht</div><div class=\"sam-definitie-body\">de macht die de wetten uitvoert, de regering.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Rechterlijke macht</div><div class=\"sam-definitie-body\">de macht die recht spreekt, de rechters.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Regering</div><div class=\"sam-definitie-body\">de koning en de ministers samen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Parlement</div><div class=\"sam-definitie-body\">de volksvertegenwoordiging: de Eerste en Tweede Kamer.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Tweede Kamer</div><div class=\"sam-definitie-body\">de gekozen Kamer die wetten maakt en de regering controleert.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Eerste Kamer</div><div class=\"sam-definitie-body\">de Kamer die wetsvoorstellen goed- of afkeurt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Democratie</div><div class=\"sam-definitie-body\">een bestuur waarin het volk zijn vertegenwoordigers kiest.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verzorgingsstaat</div><div class=\"sam-definitie-body\">een staat die zorgt voor het welzijn van de burgers.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Grondwet»</b> is de hoogste wet, terwijl <b>«Grondrecht»</b> recht voor iedereen is. <b>«Trias Politica»</b> is scheiding van machten, terwijl <b>«Democratie»</b> het volk kiest is. <b>«Wetgevende macht»</b> is maakt wetten, terwijl <b>«Uitvoerende macht»</b> voert wetten uit is. <b>«Rechterlijke macht»</b> is spreekt recht, terwijl <b>«Wetgevende macht»</b> maakt wetten is.</div>"},"C":{"sv":[{"v":"Wat veranderde tijdens de industriële revolutie?","o":["Productie ging naar fabrieken","Alles bleef handwerk","Er kwamen minder machines","Steden krompen"],"c":0,"d":2,"u":"Productie met machines in fabrieken.","uo":["Klopt: productie met machines in fabrieken.","Juist niet, het juiste antwoord is «Productie ging naar fabrieken».","Juist meer, het juiste antwoord is «Productie ging naar fabrieken».","Steden groeiden."],"uh":"Productie met machines in fabrieken."},{"v":"Wat dreef de fabrieken en treinen aan?","o":["Meteen elektriciteit","De stoommachine","De wind","Zonne-energie"],"c":1,"d":2,"u":"De stoommachine.","uo":["Kwam later, het juiste antwoord is «De stoommachine».","Klopt: de stoommachine.","Nee, het juiste antwoord is «De stoommachine».","Nee, het juiste antwoord is «De stoommachine»."],"uh":"De stoommachine."},{"v":"Wat was de sociale kwestie?","o":["Een oorlog","Een nieuwe wet","Slechte omstandigheden van arbeiders","Een belasting"],"c":2,"d":2,"u":"De slechte leef- en werkomstandigheden.","uo":["Nee, het juiste antwoord is «Slechte omstandigheden van arbeiders».","Nee, het juiste antwoord is «Slechte omstandigheden van arbeiders».","Klopt: de slechte leef- en werkomstandigheden.","Nee, het juiste antwoord is «Slechte omstandigheden van arbeiders»."],"uh":"Slechte omstandigheden van arbeiders: De slechte leef- en werkomstandigheden."},{"v":"Wat deden arbeiders om betere omstandigheden af te dwingen?","o":["Belasting betalen","Emigreren","Niets","Staken en vakbonden vormen"],"c":3,"d":3,"u":"Ze staakten en verenigden zich in vakbonden.","uo":["Nee, het juiste antwoord is «Staken en vakbonden vormen».","Niet vooral.","Ze kwamen juist in actie.","Klopt: ze staakten en verenigden zich in vakbonden."],"uh":"Staken en vakbonden vormen: Ze staakten en verenigden zich in vakbonden."},{"v":"Wat is kapitalisme?","o":["Bezit en winst voor particulieren","Alles is van de staat","Iedereen is gelijk","Er is geen geld"],"c":0,"d":2,"u":"Gebaseerd op particulier bezit en winst.","uo":["Klopt: gebaseerd op particulier bezit en winst.","Dat lijkt op socialisme.","Dat is het doel van socialisme.","Nee, het juiste antwoord is «Bezit en winst voor particulieren»."],"uh":"Bezit en winst voor particulieren: Gebaseerd op particulier bezit en winst."},{"v":"Wat is socialisme?","o":["Bezit voor enkelen","Opkomen voor gelijkheid en arbeiders","Meer macht voor de koning","Minder regels"],"c":1,"d":2,"u":"Gelijkheid en de arbeiders.","uo":["Dat lijkt op kapitalisme.","Klopt: gelijkheid en de arbeiders.","Nee, het juiste antwoord is «Opkomen voor gelijkheid en arbeiders».","Nee, het juiste antwoord is «Opkomen voor gelijkheid en arbeiders»."],"uh":"Opkomen voor gelijkheid en arbeiders: Gelijkheid en de arbeiders."},{"v":"Wat is kinderarbeid?","o":["Kinderen laten spelen","Kinderen naar school sturen","Kinderen laten werken in fabrieken","Kinderen belasting laten betalen"],"c":2,"d":1,"u":"Kinderen werkten in fabrieken.","uo":["Nee, het juiste antwoord is «Kinderen laten werken in fabrieken».","Juist niet, het juiste antwoord is «Kinderen laten werken in fabrieken».","Klopt: kinderen werkten in fabrieken.","Nee, het juiste antwoord is «Kinderen laten werken in fabrieken»."],"uh":"Kinderen laten werken in fabrieken: Kinderen werkten in fabrieken."},{"v":"Waarom trokken mensen naar de stad?","o":["Voor schone lucht","Voor de natuur","Voor rust","Voor werk in fabrieken"],"c":3,"d":2,"u":"Er was werk in de fabrieken (verstedelijking).","uo":["Nee, het juiste antwoord is «Voor werk in fabrieken».","Nee, het juiste antwoord is «Voor werk in fabrieken».","Nee, het juiste antwoord is «Voor werk in fabrieken».","Klopt: er was werk in de fabrieken (verstedelijking)."],"uh":"Voor werk in fabrieken: Er was werk in de fabrieken (verstedelijking)."},{"v":"Wat is een staking?","o":["Het werk neerleggen","Harder werken","Meer loon vragen zonder actie","Ontslag nemen"],"c":0,"d":2,"u":"Het werk neerleggen om eisen kracht bij te zetten.","uo":["Klopt: het werk neerleggen om eisen kracht bij te zetten.","Juist niet, het juiste antwoord is «Het werk neerleggen».","Een staking is juist actie.","Niet per se."],"uh":"Het werk neerleggen om eisen kracht bij te zetten."},{"v":"Wat deed een vakbond?","o":["Producten maken","Opkomen voor arbeiders","Belasting innen","Fabrieken bouwen"],"c":1,"d":2,"u":"De vakbond kwam op voor arbeiders.","uo":["Nee, het juiste antwoord is «Opkomen voor arbeiders».","Klopt: de vakbond kwam op voor arbeiders.","Nee, het juiste antwoord is «Opkomen voor arbeiders».","Nee, het juiste antwoord is «Opkomen voor arbeiders»."],"uh":"Opkomen voor arbeiders: De vakbond kwam op voor arbeiders."},{"v":"Wat maakte massaproductie mogelijk?","o":["Minder arbeiders","Handwerk thuis","Machines in fabrieken","Meer natuur"],"c":2,"d":3,"u":"Met machines veel tegelijk maken.","uo":["Nee, het juiste antwoord is «Machines in fabrieken».","Juist niet, het juiste antwoord is «Machines in fabrieken».","Klopt: met machines veel tegelijk maken.","Nee, het juiste antwoord is «Machines in fabrieken»."],"uh":"Machines in fabrieken: Met machines veel tegelijk maken."}],"begrippen":[{"t":"Industriële revolutie","d":"de overgang naar productie met machines in fabrieken"},{"t":"Fabriek","d":"een gebouw waar met machines massaal wordt geproduceerd"},{"t":"Stoommachine","d":"een machine die met stoom fabrieken en treinen aandreef"},{"t":"Verstedelijking","d":"de groei van steden door de industrie"},{"t":"Sociale kwestie","d":"de slechte leef- en werkomstandigheden van arbeiders"},{"t":"Kinderarbeid","d":"het laten werken van kinderen in fabrieken"},{"t":"Arbeider","d":"iemand die tegen loon in een fabriek werkt"},{"t":"Vakbond","d":"een organisatie die opkomt voor arbeiders"},{"t":"Staking","d":"het neerleggen van het werk om eisen kracht bij te zetten"},{"t":"Kapitalisme","d":"een economie gebaseerd op particulier bezit en winst"},{"t":"Socialisme","d":"een stroming die opkomt voor gelijkheid en de arbeiders"},{"t":"Massaproductie","d":"het in grote hoeveelheden maken van producten"}],"sam":"<div class=\"sam-intro\">Tijdens de <strong>industriële revolutie</strong> ging productie van handwerk naar <strong>fabrieken</strong> met machines. Steden groeiden en er ontstond een <strong>sociale kwestie</strong>, waartegen <strong>vakbonden</strong> en <strong>stakingen</strong> opkwamen.</div><div class=\"sam-head\">1. De industriële revolutie</div><p>Vanaf de negentiende eeuw veranderde de productie ingrijpend: de <strong>industriële revolutie</strong>. In plaats van thuis met de hand werd er in <strong>fabrieken</strong> met machines geproduceerd, aangedreven door de <strong>stoommachine</strong>. Dit maakte <strong>massaproductie</strong> mogelijk en zorgde voor <strong>verstedelijking</strong>: mensen trokken voor werk naar de stad.</p><div class=\"sam-head\">2. De sociale kwestie</div><p>De arbeiders leefden en werkten onder slechte omstandigheden: de <strong>sociale kwestie</strong>. Er was veel <strong>kinderarbeid</strong>. <strong>Arbeiders</strong> verenigden zich in <strong>vakbonden</strong> en gebruikten de <strong>staking</strong> als middel. Tegenover het <strong>kapitalisme</strong> (bezit en winst) ontstond het <strong>socialisme</strong>, dat opkwam voor gelijkheid.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Industriële revolutie</div><div class=\"sam-definitie-body\">de overgang naar productie met machines in fabrieken.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Fabriek</div><div class=\"sam-definitie-body\">een gebouw waar met machines massaal wordt geproduceerd.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Stoommachine</div><div class=\"sam-definitie-body\">een machine die met stoom fabrieken en treinen aandreef.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verstedelijking</div><div class=\"sam-definitie-body\">de groei van steden door de industrie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Sociale kwestie</div><div class=\"sam-definitie-body\">de slechte leef- en werkomstandigheden van arbeiders.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kinderarbeid</div><div class=\"sam-definitie-body\">het laten werken van kinderen in fabrieken.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Arbeider</div><div class=\"sam-definitie-body\">iemand die tegen loon in een fabriek werkt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vakbond</div><div class=\"sam-definitie-body\">een organisatie die opkomt voor arbeiders.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Staking</div><div class=\"sam-definitie-body\">het neerleggen van het werk om eisen kracht bij te zetten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kapitalisme</div><div class=\"sam-definitie-body\">een economie gebaseerd op particulier bezit en winst.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Socialisme</div><div class=\"sam-definitie-body\">een stroming die opkomt voor gelijkheid en de arbeiders.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Massaproductie</div><div class=\"sam-definitie-body\">het in grote hoeveelheden maken van producten.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Industriële revolutie»</b> is productie met machines, terwijl <b>«Massaproductie»</b> veel tegelijk maken is. <b>«Fabriek»</b> is gebouw met machines, terwijl <b>«Stoommachine»</b> machine op stoom is. <b>«Verstedelijking»</b> is steden groeien, terwijl <b>«Massaproductie»</b> veel tegelijk maken is. <b>«Sociale kwestie»</b> is ellende van arbeiders, terwijl <b>«Kinderarbeid»</b> kinderen in de fabriek is.</div>"},"D":{"sv":[{"v":"Wat is een verzorgingsstaat?","o":["Een staat die voor het welzijn zorgt","Een staat zonder regels","Een dictatuur","Een bedrijf"],"c":0,"d":2,"u":"De overheid zorgt voor het welzijn van burgers.","uo":["Klopt: de overheid zorgt voor het welzijn van burgers.","Nee, het juiste antwoord is «Een staat die voor het welzijn zorgt».","Nee, het juiste antwoord is «Een staat die voor het welzijn zorgt».","Nee, het juiste antwoord is «Een staat die voor het welzijn zorgt»."],"uh":"Een staat die voor het welzijn zorgt: De overheid zorgt voor het welzijn van burgers."},{"v":"Waarvoor is sociale zekerheid?","o":["Voor de winst","Voor inkomen bij tegenslag","Voor de export","Voor de koning"],"c":1,"d":2,"u":"Inkomen bij ziekte, werkloosheid of ouderdom.","uo":["Nee, het juiste antwoord is «Voor inkomen bij tegenslag».","Klopt: inkomen bij ziekte, werkloosheid of ouderdom.","Nee, het juiste antwoord is «Voor inkomen bij tegenslag».","Nee, het juiste antwoord is «Voor inkomen bij tegenslag»."],"uh":"Voor inkomen bij tegenslag: Inkomen bij ziekte, werkloosheid of ouderdom."},{"v":"Wat is een uitkering?","o":["Een lening","Een belasting","Geld bij te weinig inkomen","Een boete"],"c":2,"d":1,"u":"Geld van de overheid bij te weinig inkomen.","uo":["Nee, het juiste antwoord is «Geld bij te weinig inkomen».","Nee, het juiste antwoord is «Geld bij te weinig inkomen».","Klopt: geld van de overheid bij te weinig inkomen.","Nee, het juiste antwoord is «Geld bij te weinig inkomen»."],"uh":"Geld bij te weinig inkomen: Geld van de overheid bij te weinig inkomen."},{"v":"Wat is de AOW?","o":["Een bedrijfspensioen","Een verzekering","Een belasting","Het staatspensioen voor ouderen"],"c":3,"d":2,"u":"De AOW is het staatspensioen voor ouderen.","uo":["Nee, het juiste antwoord is «Het staatspensioen voor ouderen».","Nee, het juiste antwoord is «Het staatspensioen voor ouderen».","Nee, het juiste antwoord is «Het staatspensioen voor ouderen».","Klopt: de AOW is het staatspensioen voor ouderen."],"uh":"Het staatspensioen voor ouderen: De AOW is het staatspensioen voor ouderen."},{"v":"Wat betekent solidariteit?","o":["Samen risico's dragen","Ieder voor zich","Meer belasting","Minder regels"],"c":0,"d":2,"u":"Samen de lasten en risico's dragen.","uo":["Klopt: samen de lasten en risico's dragen.","Juist niet, het juiste antwoord is «Samen risico's dragen».","Nee, het juiste antwoord is «Samen risico's dragen».","Nee, het juiste antwoord is «Samen risico's dragen»."],"uh":"Samen risico's dragen: Samen de lasten en risico's dragen."},{"v":"Wat is bijstand?","o":["Een pensioen","Een uitkering voor wie geen inkomen heeft","Een belasting","Een verzekering"],"c":1,"d":2,"u":"Het laatste vangnet.","uo":["Nee, het juiste antwoord is «Een uitkering voor wie geen inkomen heeft».","Klopt: het laatste vangnet.","Nee, het juiste antwoord is «Een uitkering voor wie geen inkomen heeft».","Nee, het juiste antwoord is «Een uitkering voor wie geen inkomen heeft»."],"uh":"Een uitkering voor wie geen inkomen heeft: Het laatste vangnet."},{"v":"Wanneer bouwde Nederland de verzorgingsstaat op?","o":["Vóór 1800","In de middeleeuwen","Na 1945","Nooit"],"c":2,"d":2,"u":"Vooral na de Tweede Wereldoorlog.","uo":["Nee, het juiste antwoord is «Na 1945».","Nee, het juiste antwoord is «Na 1945».","Klopt: vooral na de Tweede Wereldoorlog.","Nee, het juiste antwoord is «Na 1945»."],"uh":"Na 1945: Vooral na de Tweede Wereldoorlog."},{"v":"Wat is een sociale wet?","o":["Een belastingwet","Een verkeerswet","Een handelswet","Een wet die tegen armoede beschermt"],"c":3,"d":2,"u":"Beschermt burgers tegen armoede of ziekte.","uo":["Nee, het juiste antwoord is «Een wet die tegen armoede beschermt».","Nee, het juiste antwoord is «Een wet die tegen armoede beschermt».","Nee, het juiste antwoord is «Een wet die tegen armoede beschermt».","Klopt: beschermt burgers tegen armoede of ziekte."],"uh":"Een wet die tegen armoede beschermt: Beschermt burgers tegen armoede of ziekte."},{"v":"Wat is werkloosheid?","o":["Geen werk hebben","Veel werk hebben","Op vakantie zijn","Met pensioen zijn"],"c":0,"d":1,"u":"Mensen hebben geen werk.","uo":["Klopt: mensen hebben geen werk.","Juist niet, het juiste antwoord is «Geen werk hebben».","Nee, het juiste antwoord is «Geen werk hebben».","Dat is iets anders."],"uh":"Geen werk hebben: Mensen hebben geen werk."},{"v":"Wat is een pensioen?","o":["Loon tijdens je werk","Inkomen na je werkzame leven","Een uitkering bij ziekte","Een studiebeurs"],"c":1,"d":2,"u":"Inkomen na je werkende jaren.","uo":["Nee, het juiste antwoord is «Inkomen na je werkzame leven».","Klopt: inkomen na je werkende jaren.","Nee, het juiste antwoord is «Inkomen na je werkzame leven».","Nee, het juiste antwoord is «Inkomen na je werkzame leven»."],"uh":"Inkomen na je werkende jaren."},{"v":"Waarvoor betaal je premie?","o":["Voor een keurmerk","Voor de export","Voor een verzekering","Voor een lening"],"c":2,"d":1,"u":"Premie betaal je voor een verzekering.","uo":["Nee, het juiste antwoord is «Voor een verzekering».","Nee, het juiste antwoord is «Voor een verzekering».","Klopt: premie betaal je voor een verzekering.","Nee, het juiste antwoord is «Voor een verzekering»."],"uh":"Voor een verzekering: Premie betaal je voor een verzekering."}],"begrippen":[{"t":"Sociale zekerheid","d":"het stelsel dat mensen bij tegenslag inkomen geeft"},{"t":"Verzorgingsstaat","d":"een staat die voor het welzijn van de burgers zorgt"},{"t":"Sociale wet","d":"een wet die burgers beschermt tegen armoede of ziekte"},{"t":"Uitkering","d":"geld van de overheid voor wie niet genoeg inkomen heeft"},{"t":"Werkloosheid","d":"de situatie waarin mensen geen werk hebben"},{"t":"AOW","d":"het staatspensioen voor ouderen"},{"t":"Solidariteit","d":"het samen dragen van risico's en lasten"},{"t":"Verzekering","d":"een afspraak die je beschermt tegen financiële risico's"},{"t":"Pensioen","d":"inkomen na je werkzame leven"},{"t":"Bijstand","d":"een uitkering voor wie geen ander inkomen heeft"},{"t":"Premie","d":"het bedrag dat je periodiek voor een verzekering betaalt"},{"t":"Collectieve voorziening","d":"iets dat de overheid voor iedereen regelt"}],"sam":"<div class=\"sam-intro\">Na 1945 bouwde Nederland een <strong>verzorgingsstaat</strong>: met <strong>sociale wetten</strong> en <strong>uitkeringen</strong> beschermt de <strong>sociale zekerheid</strong> mensen tegen tegenslag. Dat berust op <strong>solidariteit</strong>.</div><div class=\"sam-head\">1. De verzorgingsstaat</div><p>In een <strong>verzorgingsstaat</strong> zorgt de overheid voor het welzijn van de burgers. Via <strong>sociale wetten</strong> en de <strong>sociale zekerheid</strong> krijgen mensen inkomen bij ziekte, werkloosheid of ouderdom. Dit werkt door <strong>solidariteit</strong>: gezonde en werkende mensen betalen mee voor wie het (even) niet redt.</p><div class=\"sam-head\">2. Uitkeringen en pensioen</div><p>Wie geen werk heeft (<strong>werkloosheid</strong>) kan een <strong>uitkering</strong> krijgen; wie helemaal geen inkomen heeft, valt terug op de <strong>bijstand</strong>. Ouderen ontvangen de <strong>AOW</strong> en vaak een aanvullend <strong>pensioen</strong>. Voor verzekeringen betaal je <strong>premie</strong>. Voorzieningen die er voor iedereen zijn, heten <strong>collectieve voorzieningen</strong>.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Sociale zekerheid</div><div class=\"sam-definitie-body\">het stelsel dat mensen bij tegenslag inkomen geeft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verzorgingsstaat</div><div class=\"sam-definitie-body\">een staat die voor het welzijn van de burgers zorgt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Sociale wet</div><div class=\"sam-definitie-body\">een wet die burgers beschermt tegen armoede of ziekte.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Uitkering</div><div class=\"sam-definitie-body\">geld van de overheid voor wie niet genoeg inkomen heeft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Werkloosheid</div><div class=\"sam-definitie-body\">de situatie waarin mensen geen werk hebben.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">AOW</div><div class=\"sam-definitie-body\">het staatspensioen voor ouderen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Solidariteit</div><div class=\"sam-definitie-body\">het samen dragen van risico's en lasten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verzekering</div><div class=\"sam-definitie-body\">een afspraak die je beschermt tegen financiële risico's.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Pensioen</div><div class=\"sam-definitie-body\">inkomen na je werkzame leven.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Bijstand</div><div class=\"sam-definitie-body\">een uitkering voor wie geen ander inkomen heeft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Premie</div><div class=\"sam-definitie-body\">het bedrag dat je periodiek voor een verzekering betaalt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Collectieve voorziening</div><div class=\"sam-definitie-body\">iets dat de overheid voor iedereen regelt.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Sociale zekerheid»</b> is inkomen bij tegenslag, terwijl <b>«Verzorgingsstaat»</b> staat zorgt voor burgers is. <b>«Sociale wet»</b> is beschermende wet, terwijl <b>«Sociale zekerheid»</b> inkomen bij tegenslag is. <b>«Uitkering»</b> is geld bij te weinig inkomen, terwijl <b>«Bijstand»</b> laatste vangnet is. <b>«Werkloosheid»</b> is geen werk hebben, terwijl <b>«Bijstand»</b> laatste vangnet is.</div>"},"E":{"sv":[{"v":"Wat was verzuiling?","o":["De samenleving in aparte groepen","Eén grote groep","Geen groepen","Alleen jongeren"],"c":0,"d":2,"u":"Aparte groepen naar geloof en politiek.","uo":["Klopt: aparte groepen naar geloof en politiek.","Juist niet, het juiste antwoord is «De samenleving in aparte groepen».","Nee, het juiste antwoord is «De samenleving in aparte groepen».","Nee, het juiste antwoord is «De samenleving in aparte groepen»."],"uh":"De samenleving in aparte groepen: Aparte groepen naar geloof en politiek."},{"v":"Wat is ontzuiling?","o":["Meer zuilen","De zuilen verdwijnen","Strengere zuilen","Een nieuwe zuil"],"c":1,"d":2,"u":"De scheiding tussen groepen verdween.","uo":["Nee, het juiste antwoord is «De zuilen verdwijnen».","Klopt: de scheiding tussen groepen verdween.","Nee, het juiste antwoord is «De zuilen verdwijnen».","Nee, het juiste antwoord is «De zuilen verdwijnen»."],"uh":"De zuilen verdwijnen: De scheiding tussen groepen verdween."},{"v":"Wat is emancipatie?","o":["Meer regels","Minder rechten","Streven naar gelijke rechten","Een geloof"],"c":2,"d":2,"u":"Streven naar gelijke rechten, bv. van vrouwen.","uo":["Nee, het juiste antwoord is «Streven naar gelijke rechten».","Juist meer, het juiste antwoord is «Streven naar gelijke rechten».","Klopt: streven naar gelijke rechten, bv. van vrouwen.","Nee, het juiste antwoord is «Streven naar gelijke rechten»."],"uh":"Streven naar gelijke rechten, bv. van vrouwen."},{"v":"Wat ontstond er onder jongeren na 1945?","o":["Meer verzuiling","Minder muziek","Meer regels","Een eigen jongerencultuur"],"c":3,"d":2,"u":"Een eigen stijl, muziek en ideeën.","uo":["Juist niet, het juiste antwoord is «Een eigen jongerencultuur».","Nee, het juiste antwoord is «Een eigen jongerencultuur».","Nee, het juiste antwoord is «Een eigen jongerencultuur».","Klopt: een eigen stijl, muziek en ideeën."],"uh":"Een eigen stijl, muziek en ideeën."},{"v":"Wat is een consumptiemaatschappij?","o":["Een samenleving die veel koopt","Een samenleving die weinig koopt","Een dictatuur","Een standensamenleving"],"c":0,"d":2,"u":"Er wordt veel gekocht.","uo":["Klopt: er wordt veel gekocht.","Juist niet, het juiste antwoord is «Een samenleving die veel koopt».","Nee, het juiste antwoord is «Een samenleving die veel koopt».","Nee, het juiste antwoord is «Een samenleving die veel koopt»."],"uh":"Een samenleving die veel koopt: Er wordt veel gekocht."},{"v":"Wat betekent individualisering?","o":["De groep telt meer","Het individu wordt belangrijker","Meer regels","Minder vrijheid"],"c":1,"d":2,"u":"Het individu voorop.","uo":["Juist niet, het juiste antwoord is «Het individu wordt belangrijker».","Klopt: het individu voorop.","Nee, het juiste antwoord is «Het individu wordt belangrijker».","Nee, het juiste antwoord is «Het individu wordt belangrijker»."],"uh":"Het individu voorop."},{"v":"Wat is democratisering?","o":["Meer koningen","Minder inspraak","Meer inspraak krijgen","Minder rechten"],"c":2,"d":2,"u":"Mensen kregen meer inspraak.","uo":["Nee, het juiste antwoord is «Meer inspraak krijgen».","Juist niet, het juiste antwoord is «Meer inspraak krijgen».","Klopt: mensen kregen meer inspraak.","Nee, het juiste antwoord is «Meer inspraak krijgen»."],"uh":"Meer inspraak krijgen: Mensen kregen meer inspraak."},{"v":"Wat vergrootte de kloof tussen jong en oud?","o":["Meer verzuiling","Minder muziek","Meer belasting","Massamedia en jongerencultuur"],"c":3,"d":3,"u":"Eigen jongerencultuur en massamedia.","uo":["Nee, het juiste antwoord is «Massamedia en jongerencultuur».","Nee, het juiste antwoord is «Massamedia en jongerencultuur».","Nee, het juiste antwoord is «Massamedia en jongerencultuur».","Klopt: eigen jongerencultuur en massamedia."],"uh":"Massamedia en jongerencultuur: Eigen jongerencultuur en massamedia."},{"v":"Wat is secularisatie?","o":["Minder geloof","Meer geloof","Meer regels","Een traditie"],"c":0,"d":1,"u":"Religie wordt minder belangrijk.","uo":["Klopt: religie wordt minder belangrijk.","Juist niet, het juiste antwoord is «Minder geloof».","Nee, het juiste antwoord is «Minder geloof».","Nee, het juiste antwoord is «Minder geloof»."],"uh":"Minder geloof: Religie wordt minder belangrijk."},{"v":"Wat is een protestbeweging?","o":["Een regeringspartij","Een groep die zich verzet","Een bedrijf","Alleen een vakbond"],"c":1,"d":2,"u":"Verzet tegen bestaande regels.","uo":["Nee, het juiste antwoord is «Een groep die zich verzet».","Klopt: verzet tegen bestaande regels.","Nee, het juiste antwoord is «Een groep die zich verzet».","Niet per se."],"uh":"Een groep die zich verzet: Verzet tegen bestaande regels."},{"v":"Wat maakte de welvaart na 1945 mogelijk?","o":["Meer verzuiling","Een oorlog","Economische groei","Minder werk"],"c":2,"d":2,"u":"De economie groeide sterk.","uo":["Nee, het juiste antwoord is «Economische groei».","Nee, het juiste antwoord is «Economische groei».","Klopt: de economie groeide sterk.","Nee, het juiste antwoord is «Economische groei»."],"uh":"Economische groei: De economie groeide sterk."}],"begrippen":[{"t":"Verzuiling","d":"de indeling van de samenleving in aparte groepen naar geloof of politiek"},{"t":"Ontzuiling","d":"het verdwijnen van de scheiding tussen die groepen"},{"t":"Emancipatie","d":"het streven naar gelijke rechten, bijvoorbeeld van vrouwen"},{"t":"Jongerencultuur","d":"de eigen stijl, muziek en ideeën van jongeren"},{"t":"Protestbeweging","d":"een groep die zich verzet tegen bestaande regels"},{"t":"Welvaart","d":"de mate waarin mensen in hun behoeften kunnen voorzien"},{"t":"Consumptiemaatschappij","d":"een samenleving waarin veel wordt gekocht en gebruikt"},{"t":"Individualisering","d":"het belangrijker worden van het individu"},{"t":"Secularisatie","d":"het minder belangrijk worden van religie"},{"t":"Democratisering","d":"het krijgen van meer inspraak en zeggenschap"},{"t":"Massamedia","d":"media die veel mensen tegelijk bereiken, zoals tv en radio"},{"t":"Generatiekloof","d":"het verschil in opvattingen tussen jong en oud"}],"sam":"<div class=\"sam-intro\">Na de oorlog verdween de <strong>verzuiling</strong> en kwam de <strong>emancipatie</strong> op gang. Er ontstond een eigen <strong>jongerencultuur</strong>, en door groeiende <strong>welvaart</strong> een <strong>consumptiemaatschappij</strong>.</div><div class=\"sam-head\">1. Ontzuiling en emancipatie</div><p>Vóór 1960 was de samenleving verdeeld in aparte groepen naar geloof en politiek: de <strong>verzuiling</strong>. Daarna verdwenen die scheidslijnen: de <strong>ontzuiling</strong>. Tegelijk vond <strong>emancipatie</strong> plaats (bijvoorbeeld van vrouwen) en <strong>democratisering</strong>: mensen kregen meer inspraak. Ook de <strong>secularisatie</strong> zette door.</p><div class=\"sam-head\">2. Jongeren, welvaart en protest</div><p>Jongeren ontwikkelden een eigen <strong>jongerencultuur</strong> met eigen muziek en ideeën, en vormden <strong>protestbewegingen</strong>. Door de stijgende <strong>welvaart</strong> ontstond een <strong>consumptiemaatschappij</strong> en nam de <strong>individualisering</strong> toe. De opkomst van de <strong>massamedia</strong> vergrootte soms de <strong>generatiekloof</strong> tussen jong en oud.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verzuiling</div><div class=\"sam-definitie-body\">de indeling van de samenleving in aparte groepen naar geloof of politiek.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Ontzuiling</div><div class=\"sam-definitie-body\">het verdwijnen van de scheiding tussen die groepen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Emancipatie</div><div class=\"sam-definitie-body\">het streven naar gelijke rechten, bijvoorbeeld van vrouwen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Jongerencultuur</div><div class=\"sam-definitie-body\">de eigen stijl, muziek en ideeën van jongeren.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Protestbeweging</div><div class=\"sam-definitie-body\">een groep die zich verzet tegen bestaande regels.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Welvaart</div><div class=\"sam-definitie-body\">de mate waarin mensen in hun behoeften kunnen voorzien.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Consumptiemaatschappij</div><div class=\"sam-definitie-body\">een samenleving waarin veel wordt gekocht en gebruikt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Individualisering</div><div class=\"sam-definitie-body\">het belangrijker worden van het individu.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Secularisatie</div><div class=\"sam-definitie-body\">het minder belangrijk worden van religie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Democratisering</div><div class=\"sam-definitie-body\">het krijgen van meer inspraak en zeggenschap.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Massamedia</div><div class=\"sam-definitie-body\">media die veel mensen tegelijk bereiken, zoals tv en radio.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Generatiekloof</div><div class=\"sam-definitie-body\">het verschil in opvattingen tussen jong en oud.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Verzuiling»</b> is samenleving in zuilen, terwijl <b>«Ontzuiling»</b> zuilen verdwijnen is. <b>«Emancipatie»</b> is streven naar gelijkheid, terwijl <b>«Democratisering»</b> meer inspraak is. <b>«Jongerencultuur»</b> is eigen stijl van jongeren, terwijl <b>«Protestbeweging»</b> groep die zich verzet is. <b>«Welvaart»</b> is hoe goed men rondkomt, terwijl <b>«Consumptiemaatschappij»</b> veel kopen is.</div>"},"F":{"sv":[{"v":"Wat is een kolonie?","o":["Een gebied bestuurd door een ander land","Een vrij land","Een stad","Een bedrijf"],"c":0,"d":1,"u":"Een gebied dat een ander land bestuurt.","uo":["Klopt: een gebied dat een ander land bestuurt.","Juist niet, het juiste antwoord is «Een gebied bestuurd door een ander land».","Nee, het juiste antwoord is «Een gebied bestuurd door een ander land».","Nee, het juiste antwoord is «Een gebied bestuurd door een ander land»."],"uh":"Een gebied dat een ander land bestuurt."},{"v":"Wat is dekolonisatie?","o":["Een gebied veroveren","Koloniën worden onafhankelijk","Een kolonie stichten","Een oorlog beginnen"],"c":1,"d":2,"u":"Koloniën worden zelfstandig.","uo":["Dat is kolonisatie.","Klopt: koloniën worden zelfstandig.","Idem, het juiste antwoord is «Koloniën worden onafhankelijk».","Nee, het juiste antwoord is «Koloniën worden onafhankelijk»."],"uh":"Koloniën worden zelfstandig."},{"v":"Welke kolonie werd Indonesië?","o":["België","Suriname","Nederlands-Indië","Congo"],"c":2,"d":1,"u":"Nederlands-Indië werd Indonesië.","uo":["Nee, het juiste antwoord is «Nederlands-Indië».","Suriname is iets anders.","Klopt: Nederlands-Indië werd Indonesië.","Nee, het juiste antwoord is «Nederlands-Indië»."],"uh":"Nederlands-Indië werd Indonesië."},{"v":"Wanneer werd Suriname onafhankelijk?","o":["In 1900","In 1600","Nooit","In 1975"],"c":3,"d":2,"u":"Het juiste antwoord is: In 1975.","uo":["Nee, het juiste antwoord is «In 1975».","Nee, het juiste antwoord is «In 1975».","Suriname is wel onafhankelijk.","Klopt: in 1975."],"uh":"In 1975: Het juiste antwoord is: In 1975."},{"v":"Wat is nationalisme?","o":["Streven naar een eigen natie","Een gebied veroveren","Belasting innen","Handel drijven"],"c":0,"d":2,"u":"Streven naar een eigen zelfstandige natie.","uo":["Klopt: streven naar een eigen zelfstandige natie.","Nee, het juiste antwoord is «Streven naar een eigen natie».","Nee, het juiste antwoord is «Streven naar een eigen natie».","Nee, het juiste antwoord is «Streven naar een eigen natie»."],"uh":"Streven naar een eigen zelfstandige natie."},{"v":"Wat waren de politionele acties?","o":["Politiehervormingen","Militaire acties in Indië","Verkiezingen","Een verdrag"],"c":1,"d":3,"u":"Militaire acties van Nederland in Indië na 1945.","uo":["Nee, het juiste antwoord is «Militaire acties in Indië».","Klopt: militaire acties van Nederland in Indië na 1945.","Nee, het juiste antwoord is «Militaire acties in Indië».","Nee, het juiste antwoord is «Militaire acties in Indië»."],"uh":"Militaire acties van Nederland in Indië na 1945."},{"v":"Waarmee verdiende Nederland in de koloniën?","o":["Met belasting hier","Met toerisme","Met grondstoffen en plantages","Met fabrieken hier"],"c":2,"d":2,"u":"Grondstoffen en plantages, vaak door uitbuiting.","uo":["Nee, het juiste antwoord is «Met grondstoffen en plantages».","Nee, het juiste antwoord is «Met grondstoffen en plantages».","Klopt: grondstoffen en plantages, vaak door uitbuiting.","Nee, het juiste antwoord is «Met grondstoffen en plantages»."],"uh":"Met grondstoffen en plantages: Grondstoffen en plantages, vaak door uitbuiting."},{"v":"Wat is uitbuiting?","o":["Eerlijk betalen","Vrij handelen","Belasting betalen","Mensen misbruiken voor winst"],"c":3,"d":2,"u":"Mensen of gebieden misbruiken voor winst.","uo":["Juist niet, het juiste antwoord is «Mensen misbruiken voor winst».","Nee, het juiste antwoord is «Mensen misbruiken voor winst».","Nee, het juiste antwoord is «Mensen misbruiken voor winst».","Klopt: mensen of gebieden misbruiken voor winst."],"uh":"Mensen misbruiken voor winst: Mensen of gebieden misbruiken voor winst."},{"v":"Wat is kolonisatie?","o":["Een gebied in bezit nemen","Een land bevrijden","Handel drijven","Een verdrag sluiten"],"c":0,"d":2,"u":"Een ander gebied in bezit nemen en besturen.","uo":["Klopt: een ander gebied in bezit nemen en besturen.","Juist het tegenovergestelde.","Nee, het juiste antwoord is «Een gebied in bezit nemen».","Nee, het juiste antwoord is «Een gebied in bezit nemen»."],"uh":"Een gebied in bezit nemen: Een ander gebied in bezit nemen en besturen."},{"v":"Wat gebeurde na de onafhankelijkheid van Suriname?","o":["Iedereen bleef","Veel mensen migreerden naar Nederland","Er kwam oorlog hier","Niets veranderde"],"c":1,"d":3,"u":"Veel mensen kwamen naar Nederland.","uo":["Niet iedereen.","Klopt: veel mensen kwamen naar Nederland.","Nee, het juiste antwoord is «Veel mensen migreerden naar Nederland».","Er veranderde veel."],"uh":"Veel mensen kwamen naar Nederland."},{"v":"Wat is een plantage?","o":["Een school","Een fabriek in Nederland","Een groot landbouwbedrijf in een kolonie","Een haven"],"c":2,"d":1,"u":"Een groot landbouwbedrijf in een kolonie.","uo":["Nee, het juiste antwoord is «Een groot landbouwbedrijf in een kolonie».","Nee, het juiste antwoord is «Een groot landbouwbedrijf in een kolonie».","Klopt: een groot landbouwbedrijf in een kolonie.","Nee, het juiste antwoord is «Een groot landbouwbedrijf in een kolonie»."],"uh":"Een groot landbouwbedrijf in een kolonie."}],"begrippen":[{"t":"Kolonie","d":"een gebied dat door een ander land wordt bestuurd"},{"t":"Kolonisatie","d":"het in bezit nemen en besturen van een ander gebied"},{"t":"Dekolonisatie","d":"het onafhankelijk worden van koloniën"},{"t":"Nederlands-Indië","d":"de vroegere Nederlandse kolonie, nu Indonesië"},{"t":"Onafhankelijkheid","d":"het zelfstandig worden van een land"},{"t":"Nationalisme","d":"het streven naar een eigen zelfstandige natie"},{"t":"Uitbuiting","d":"het misbruiken van mensen of gebieden voor winst"},{"t":"Plantage","d":"een groot landbouwbedrijf in een kolonie"},{"t":"Politionele acties","d":"de militaire acties van Nederland in Indië na 1945"},{"t":"Suriname","d":"een vroegere Nederlandse kolonie, sinds 1975 onafhankelijk"},{"t":"Migratie","d":"het verhuizen van mensen, zoals van Suriname naar Nederland"},{"t":"Slavernij","d":"het bezit en dwingen van mensen tot onbetaalde arbeid"}],"sam":"<div class=\"sam-intro\">Nederland bestuurde <strong>koloniën</strong> zoals <strong>Nederlands-Indië</strong> en <strong>Suriname</strong>. Na 1945 leidde het <strong>nationalisme</strong> tot <strong>dekolonisatie</strong>: koloniën werden <strong>onafhankelijk</strong>.</div><div class=\"sam-head\">1. Koloniën</div><p>Een <strong>kolonie</strong> is een gebied dat door een ander land wordt bestuurd; het in bezit nemen ervan heet <strong>kolonisatie</strong>. Nederland verdiende in zijn koloniën aan grondstoffen en <strong>plantages</strong>, vaak door <strong>uitbuiting</strong> van de bevolking. In het verleden hoorde daar ook <strong>slavernij</strong> bij.</p><div class=\"sam-head\">2. Onafhankelijkheid</div><p>Na de Tweede Wereldoorlog groeide het <strong>nationalisme</strong>: het streven naar een eigen natie. Dat leidde tot <strong>dekolonisatie</strong>. <strong>Nederlands-Indië</strong> werd na de <strong>politionele acties</strong> onafhankelijk als Indonesië; <strong>Suriname</strong> werd zelfstandig in 1975. Veel mensen kwamen daarna via <strong>migratie</strong> naar Nederland.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kolonie</div><div class=\"sam-definitie-body\">een gebied dat door een ander land wordt bestuurd.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kolonisatie</div><div class=\"sam-definitie-body\">het in bezit nemen en besturen van een ander gebied.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Dekolonisatie</div><div class=\"sam-definitie-body\">het onafhankelijk worden van koloniën.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Nederlands-Indië</div><div class=\"sam-definitie-body\">de vroegere Nederlandse kolonie, nu Indonesië.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Onafhankelijkheid</div><div class=\"sam-definitie-body\">het zelfstandig worden van een land.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Nationalisme</div><div class=\"sam-definitie-body\">het streven naar een eigen zelfstandige natie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Uitbuiting</div><div class=\"sam-definitie-body\">het misbruiken van mensen of gebieden voor winst.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Plantage</div><div class=\"sam-definitie-body\">een groot landbouwbedrijf in een kolonie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Politionele acties</div><div class=\"sam-definitie-body\">de militaire acties van Nederland in Indië na 1945.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Suriname</div><div class=\"sam-definitie-body\">een vroegere Nederlandse kolonie, sinds 1975 onafhankelijk.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Migratie</div><div class=\"sam-definitie-body\">het verhuizen van mensen, zoals van Suriname naar Nederland.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Slavernij</div><div class=\"sam-definitie-body\">het bezit en dwingen van mensen tot onbetaalde arbeid.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Kolonie»</b> is bestuurd gebied, terwijl <b>«Plantage»</b> landbouwbedrijf in kolonie is. <b>«Kolonisatie»</b> is gebied in bezit nemen, terwijl <b>«Dekolonisatie»</b> koloniën worden vrij is. <b>«Nederlands-Indië»</b> is kolonie, nu Indonesië, terwijl <b>«Suriname»</b> kolonie, vrij in 1975 is. <b>«Onafhankelijkheid»</b> is zelfstandig worden, terwijl <b>«Nationalisme»</b> streven naar eigen natie is.</div>"},"G":{"sv":[{"v":"Wanneer was de Eerste Wereldoorlog?","o":["1914-1918","1939-1945","1900-1910","1950-1960"],"c":0,"d":1,"u":"1914 tot 1918.","uo":["Klopt: 1914 tot 1918.","Dat is de Tweede.","Nee, het juiste antwoord is «1914-1918».","Nee, het juiste antwoord is «1914-1918»."],"uh":"1914-1918: 1914 tot 1918."},{"v":"Wat is het interbellum?","o":["De tijd vóór WOI","De tijd tussen de wereldoorlogen","Een veldslag","Een verdrag"],"c":1,"d":2,"u":"De periode tussen de twee wereldoorlogen.","uo":["Nee, het juiste antwoord is «De tijd tussen de wereldoorlogen».","Klopt: de periode tussen de twee wereldoorlogen.","Nee, het juiste antwoord is «De tijd tussen de wereldoorlogen».","Nee, het juiste antwoord is «De tijd tussen de wereldoorlogen»."],"uh":"De tijd tussen de wereldoorlogen: De periode tussen de twee wereldoorlogen."},{"v":"Wat gebeurde er in 1929?","o":["De val van de Muur","Het einde van WOII","De beurskrach","De start van de EU"],"c":2,"d":2,"u":"De beurskrach leidde tot een crisis.","uo":["Nee, dat was 1989.","Nee, het juiste antwoord is «De beurskrach».","Klopt: de beurskrach leidde tot een crisis.","Nee, het juiste antwoord is «De beurskrach»."],"uh":"De beurskrach leidde tot een crisis."},{"v":"Wat is fascisme?","o":["Een democratie","Een vorm van socialisme","Een godsdienst","Extreem-rechts met één sterke leider"],"c":3,"d":2,"u":"Extreem-rechts met een sterke leider en één partij.","uo":["Juist niet, het juiste antwoord is «Extreem-rechts met één sterke leider».","Nee, het juiste antwoord is «Extreem-rechts met één sterke leider».","Nee, het juiste antwoord is «Extreem-rechts met één sterke leider».","Klopt: extreem-rechts met een sterke leider en één partij."],"uh":"Extreem-rechts met een sterke leider en één partij."},{"v":"Wat was het nazisme?","o":["Duits fascisme met racisme","Een democratie","Een vakbond","Een kerk"],"c":0,"d":2,"u":"De Duitse vorm van fascisme met Jodenhaat.","uo":["Klopt: de Duitse vorm van fascisme met Jodenhaat.","Nee, het juiste antwoord is «Duits fascisme met racisme».","Nee, het juiste antwoord is «Duits fascisme met racisme».","Nee, het juiste antwoord is «Duits fascisme met racisme»."],"uh":"Duits fascisme met racisme: De Duitse vorm van fascisme met Jodenhaat."},{"v":"Wat is de Holocaust?","o":["Een veldslag","De moord op zes miljoen Joden","Een verdrag","Een verkiezing"],"c":1,"d":2,"u":"De systematische moord op de Joden door de nazi's.","uo":["Nee, het juiste antwoord is «De moord op zes miljoen Joden».","Klopt: de systematische moord op de Joden door de nazi's.","Nee, het juiste antwoord is «De moord op zes miljoen Joden».","Nee, het juiste antwoord is «De moord op zes miljoen Joden»."],"uh":"De moord op zes miljoen Joden: De systematische moord op de Joden door de nazi's."},{"v":"Wat was de Koude Oorlog?","o":["Een wereldoorlog","Een oorlog met veldslagen","Spanning tussen VS en Sovjet-Unie","Een burgeroorlog"],"c":2,"d":2,"u":"Spanning tussen VS en Sovjet-Unie na 1945.","uo":["Nee, het juiste antwoord is «Spanning tussen VS en Sovjet-Unie».","Er werd niet direct gevochten.","Klopt: spanning tussen VS en Sovjet-Unie na 1945.","Nee, het juiste antwoord is «Spanning tussen VS en Sovjet-Unie»."],"uh":"Spanning tussen VS en Sovjet-Unie na 1945."},{"v":"Wat was de NAVO?","o":["Een communistisch pact","Een handelsverdrag","Een munt","Het westerse bondgenootschap"],"c":3,"d":2,"u":"Het militaire bondgenootschap van westerse landen.","uo":["Dat was het Warschaupact.","Nee, het juiste antwoord is «Het westerse bondgenootschap».","Nee, het juiste antwoord is «Het westerse bondgenootschap».","Klopt: het militaire bondgenootschap van westerse landen."],"uh":"Het westerse bondgenootschap: Het militaire bondgenootschap van westerse landen."},{"v":"Wat gebeurde er in 1989?","o":["De val van de Berlijnse Muur","Het begin van WOII","De beurskrach","Het begin van WOI"],"c":0,"d":2,"u":"De Muur viel, einde van de Koude Oorlog.","uo":["Klopt: de Muur viel, einde van de Koude Oorlog.","Nee, het juiste antwoord is «De val van de Berlijnse Muur».","Dat was 1929.","Nee, het juiste antwoord is «De val van de Berlijnse Muur»."],"uh":"De val van de Berlijnse Muur: De Muur viel, einde van de Koude Oorlog."},{"v":"Wat is een dictatuur?","o":["Het volk kiest","Eén persoon of partij heeft alle macht","Er zijn veel partijen","Er zijn geen leiders"],"c":1,"d":2,"u":"Alle macht bij één.","uo":["Dat is een democratie.","Klopt: alle macht bij één.","Juist niet, het juiste antwoord is «Eén persoon of partij heeft alle macht».","Nee, het juiste antwoord is «Eén persoon of partij heeft alle macht»."],"uh":"Eén persoon of partij heeft alle macht: Alle macht bij één."},{"v":"Wat betekende de bezetting voor Nederland in WOII?","o":["Er was vrede","Nederland was vrij","Een vreemd leger had de macht","Nederland won"],"c":2,"d":3,"u":"Duitsland beheerste het land.","uo":["Nee, het juiste antwoord is «Een vreemd leger had de macht».","Juist niet, het juiste antwoord is «Een vreemd leger had de macht».","Klopt: Duitsland beheerste het land.","Nee, het juiste antwoord is «Een vreemd leger had de macht»."],"uh":"Een vreemd leger had de macht: Duitsland beheerste het land."}],"begrippen":[{"t":"Eerste Wereldoorlog","d":"de oorlog van 1914 tot 1918 in vooral Europa"},{"t":"Interbellum","d":"de periode tussen de twee wereldoorlogen"},{"t":"Beurskrach van 1929","d":"de ineenstorting van de aandelenmarkt die tot een crisis leidde"},{"t":"Crisis","d":"een tijd van massale werkloosheid en armoede"},{"t":"Fascisme","d":"een extreem-rechtse stroming met een sterke leider en één partij"},{"t":"Nazisme","d":"de Duitse vorm van fascisme met racisme en Jodenhaat"},{"t":"Dictatuur","d":"een bestuur waarin één persoon of partij alle macht heeft"},{"t":"Tweede Wereldoorlog","d":"de oorlog van 1939 tot 1945"},{"t":"Bezetting","d":"de periode waarin een vreemd leger een land beheerst"},{"t":"Holocaust","d":"de systematische moord op zes miljoen Joden door de nazi's"},{"t":"Koude Oorlog","d":"de spanning tussen de VS en de Sovjet-Unie na 1945"},{"t":"NAVO","d":"het militaire bondgenootschap van westerse landen"},{"t":"Warschaupact","d":"het militaire bondgenootschap van de communistische landen"},{"t":"Val van de Muur","d":"de val van de Berlijnse Muur in 1989"}],"sam":"<div class=\"sam-intro\">De twintigste eeuw kende twee wereldoorlogen. Na de <strong>beurskrach van 1929</strong> kwamen <strong>fascisme</strong> en <strong>nazisme</strong> op. Daarna verdeelde de <strong>Koude Oorlog</strong> de wereld tot de <strong>Val van de Muur</strong> in 1989.</div><div class=\"sam-head\">1. De wereldoorlogen</div><p>De <strong>Eerste Wereldoorlog</strong> (1914-1918) werd gevolgd door het <strong>interbellum</strong>, de tijd tussen de oorlogen. In de <strong>Tweede Wereldoorlog</strong> (1939-1945) kende Nederland een <strong>bezetting</strong> door Duitsland. In die oorlog vond de <strong>Holocaust</strong> plaats: de systematische moord op zes miljoen Joden.</p><div class=\"sam-head\">2. Crisis en dictaturen</div><p>De <strong>beurskrach van 1929</strong> stortte de wereld in een economische <strong>crisis</strong> met massale werkloosheid. In die onrust kwamen extreem-rechtse stromingen op: het <strong>fascisme</strong> en, in Duitsland, het <strong>nazisme</strong> met racisme en Jodenhaat. Beide vestigden een <strong>dictatuur</strong>: alle macht bij één partij.</p><div class=\"sam-head\">3. De Koude Oorlog</div><p>Na 1945 stonden de VS en de Sovjet-Unie tegenover elkaar in de <strong>Koude Oorlog</strong>. Het Westen vormde de <strong>NAVO</strong>, het communistische blok het <strong>Warschaupact</strong>. De spanning eindigde met de <strong>Val van de Muur</strong> in Berlijn in 1989.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Eerste Wereldoorlog</div><div class=\"sam-definitie-body\">de oorlog van 1914 tot 1918 in vooral Europa.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Interbellum</div><div class=\"sam-definitie-body\">de periode tussen de twee wereldoorlogen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Beurskrach van 1929</div><div class=\"sam-definitie-body\">de ineenstorting van de aandelenmarkt die tot een crisis leidde.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Crisis</div><div class=\"sam-definitie-body\">een tijd van massale werkloosheid en armoede.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Fascisme</div><div class=\"sam-definitie-body\">een extreem-rechtse stroming met een sterke leider en één partij.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Nazisme</div><div class=\"sam-definitie-body\">de Duitse vorm van fascisme met racisme en Jodenhaat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Dictatuur</div><div class=\"sam-definitie-body\">een bestuur waarin één persoon of partij alle macht heeft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Tweede Wereldoorlog</div><div class=\"sam-definitie-body\">de oorlog van 1939 tot 1945.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Bezetting</div><div class=\"sam-definitie-body\">de periode waarin een vreemd leger een land beheerst.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Holocaust</div><div class=\"sam-definitie-body\">de systematische moord op zes miljoen Joden door de nazi's.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Koude Oorlog</div><div class=\"sam-definitie-body\">de spanning tussen de VS en de Sovjet-Unie na 1945.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">NAVO</div><div class=\"sam-definitie-body\">het militaire bondgenootschap van westerse landen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Warschaupact</div><div class=\"sam-definitie-body\">het militaire bondgenootschap van de communistische landen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Val van de Muur</div><div class=\"sam-definitie-body\">de val van de Berlijnse Muur in 1989.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Eerste Wereldoorlog»</b> is oorlog 1914-1918, terwijl <b>«Tweede Wereldoorlog»</b> oorlog 1939-1945 is. <b>«Interbellum»</b> is tussen de wereldoorlogen, terwijl <b>«Koude Oorlog»</b> VS tegen Sovjet-Unie is. <b>«Beurskrach van 1929»</b> is instorting van de beurs, terwijl <b>«Crisis»</b> werkloosheid en armoede is. <b>«Fascisme»</b> is sterke leider, één partij, terwijl <b>«Nazisme»</b> Duits fascisme met racisme is.</div>"},"H":{"sv":[{"v":"Waarom werkten Europese landen na 1945 samen?","o":["Voor vrede en welvaart","Om oorlog te voeren","Om koloniën te houden","Om grenzen te sluiten"],"c":0,"d":2,"u":"Om vrede en welvaart te bevorderen.","uo":["Klopt: om vrede en welvaart te bevorderen.","Juist niet, het juiste antwoord is «Voor vrede en welvaart».","Nee, het juiste antwoord is «Voor vrede en welvaart».","Nee, het juiste antwoord is «Voor vrede en welvaart»."],"uh":"Voor vrede en welvaart: Om vrede en welvaart te bevorderen."},{"v":"Wat is de euro?","o":["Een verdrag","De gezamenlijke munt van EU-landen","Een leger","Een belasting"],"c":1,"d":1,"u":"De munt van veel EU-landen.","uo":["Nee, het juiste antwoord is «De gezamenlijke munt van EU-landen».","Klopt: de munt van veel EU-landen.","Nee, het juiste antwoord is «De gezamenlijke munt van EU-landen».","Nee, het juiste antwoord is «De gezamenlijke munt van EU-landen»."],"uh":"De gezamenlijke munt van EU-landen: De munt van veel EU-landen."},{"v":"Wat is de Europese Unie?","o":["Een land","Een bedrijf","Een samenwerking van Europese landen","Een munt"],"c":2,"d":1,"u":"Een samenwerkingsverband van Europese landen.","uo":["Nee, het juiste antwoord is «Een samenwerking van Europese landen».","Nee, het juiste antwoord is «Een samenwerking van Europese landen».","Klopt: een samenwerkingsverband van Europese landen.","De munt is de euro."],"uh":"Een samenwerkingsverband van Europese landen."},{"v":"Wat is globalisering?","o":["Landen sluiten zich af","Minder handel","Meer grenzen","Landen raken wereldwijd verweven"],"c":3,"d":2,"u":"Landen raken wereldwijd verweven.","uo":["Juist niet, het juiste antwoord is «Landen raken wereldwijd verweven».","Nee, het juiste antwoord is «Landen raken wereldwijd verweven».","Nee, het juiste antwoord is «Landen raken wereldwijd verweven».","Klopt: landen raken wereldwijd verweven."],"uh":"Landen raken wereldwijd verweven."},{"v":"Wat is vrij verkeer in de EU?","o":["Vrij reizen, werken en handelen","Meer grenscontrole","Meer belasting","Aparte munten"],"c":0,"d":2,"u":"Vrij binnen de EU.","uo":["Klopt: vrij binnen de EU.","Juist minder.","Nee, het juiste antwoord is «Vrij reizen, werken en handelen».","Nee, het juiste antwoord is «Vrij reizen, werken en handelen»."],"uh":"Vrij reizen, werken en handelen: Vrij binnen de EU."},{"v":"Wat is een verdrag?","o":["Een oorlog","Een officiële afspraak tussen landen","Een belasting","Een munt"],"c":1,"d":1,"u":"Een afspraak tussen landen.","uo":["Nee, het juiste antwoord is «Een officiële afspraak tussen landen».","Klopt: een afspraak tussen landen.","Nee, het juiste antwoord is «Een officiële afspraak tussen landen».","Nee, het juiste antwoord is «Een officiële afspraak tussen landen»."],"uh":"Een officiële afspraak tussen landen: Een afspraak tussen landen."},{"v":"Wat is een multinational?","o":["Een overheid","Een klein winkeltje","Een bedrijf in meerdere landen","Een school"],"c":2,"d":2,"u":"Een bedrijf dat in veel landen actief is.","uo":["Nee, het juiste antwoord is «Een bedrijf in meerdere landen».","Nee, het juiste antwoord is «Een bedrijf in meerdere landen».","Klopt: een bedrijf dat in veel landen actief is.","Nee, het juiste antwoord is «Een bedrijf in meerdere landen»."],"uh":"Een bedrijf dat in veel landen actief is."},{"v":"Wat is ontwikkelingshulp?","o":["Handel met winst","Belasting innen","Een lening","Steun aan armere landen"],"c":3,"d":2,"u":"Steun aan armere landen om zich te ontwikkelen.","uo":["Nee, het juiste antwoord is «Steun aan armere landen».","Nee, het juiste antwoord is «Steun aan armere landen».","Nee, het juiste antwoord is «Steun aan armere landen».","Klopt: steun aan armere landen om zich te ontwikkelen."],"uh":"Steun aan armere landen om zich te ontwikkelen."},{"v":"Wat was het hoofddoel van de Europese samenwerking?","o":["Vrede","Meer oorlog","Meer koloniën","Aparte munten"],"c":0,"d":2,"u":"Vrede en welvaart.","uo":["Klopt: vrede en welvaart.","Juist niet, het juiste antwoord is «Vrede».","Nee, het juiste antwoord is «Vrede».","Nee, het juiste antwoord is «Vrede»."],"uh":"Vrede en welvaart."},{"v":"Wat is een vluchteling?","o":["Een toerist","Iemand die zijn land ontvlucht","Een handelaar","Een ambtenaar"],"c":1,"d":2,"u":"Iemand die zijn land ontvlucht vanwege gevaar.","uo":["Nee, het juiste antwoord is «Iemand die zijn land ontvlucht».","Klopt: iemand die zijn land ontvlucht vanwege gevaar.","Nee, het juiste antwoord is «Iemand die zijn land ontvlucht».","Nee, het juiste antwoord is «Iemand die zijn land ontvlucht»."],"uh":"Iemand die zijn land ontvlucht vanwege gevaar."},{"v":"Wat is handel tussen landen?","o":["Een verdrag","Belasting innen","Kopen en verkopen over de grens","Een oorlog"],"c":2,"d":1,"u":"Goederen kopen en verkopen tussen landen.","uo":["Nee, het juiste antwoord is «Kopen en verkopen over de grens».","Nee, het juiste antwoord is «Kopen en verkopen over de grens».","Klopt: goederen kopen en verkopen tussen landen.","Nee, het juiste antwoord is «Kopen en verkopen over de grens»."],"uh":"Kopen en verkopen over de grens: Goederen kopen en verkopen tussen landen."}],"begrippen":[{"t":"Europese Unie","d":"een samenwerkingsverband van Europese landen"},{"t":"Europese samenwerking","d":"het samenwerken van landen in Europa na 1945"},{"t":"Euro","d":"de gezamenlijke munt van veel EU-landen"},{"t":"Vrij verkeer","d":"het vrij kunnen reizen, werken en handelen binnen de EU"},{"t":"Globalisering","d":"het steeds meer verweven raken van landen wereldwijd"},{"t":"Vluchteling","d":"iemand die zijn land ontvlucht vanwege gevaar"},{"t":"Migratie","d":"het verhuizen van mensen tussen landen"},{"t":"Verdrag","d":"een officiële afspraak tussen landen"},{"t":"Vrede","d":"het ontbreken van oorlog, een doel van Europese samenwerking"},{"t":"Handel","d":"het kopen en verkopen tussen landen"},{"t":"Multinational","d":"een bedrijf dat in meerdere landen actief is"},{"t":"Ontwikkelingshulp","d":"steun aan armere landen om zich te ontwikkelen"}],"sam":"<div class=\"sam-intro\">Na 1945 kozen Europese landen voor <strong>samenwerking</strong> om <strong>vrede</strong> en welvaart te bevorderen, wat uitgroeide tot de <strong>Europese Unie</strong>. Door <strong>globalisering</strong> raken landen wereldwijd verweven.</div><div class=\"sam-head\">1. Europese samenwerking</div><p>Om herhaling van oorlog te voorkomen, begonnen Europese landen na 1945 samen te werken. Die <strong>Europese samenwerking</strong> groeide uit tot de <strong>Europese Unie</strong>, met een gezamenlijke munt, de <strong>euro</strong>, en <strong>vrij verkeer</strong> van mensen en goederen. Afspraken tussen landen worden vastgelegd in een <strong>verdrag</strong>; het hoofddoel was en is <strong>vrede</strong>.</p><div class=\"sam-head\">2. Globalisering</div><p>Door <strong>globalisering</strong> raken landen steeds meer met elkaar verweven via <strong>handel</strong> en <strong>multinationals</strong>. Mensen verplaatsen zich door <strong>migratie</strong>, soms als <strong>vluchteling</strong>. Rijke landen geven <strong>ontwikkelingshulp</strong> aan armere landen.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Europese Unie</div><div class=\"sam-definitie-body\">een samenwerkingsverband van Europese landen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Europese samenwerking</div><div class=\"sam-definitie-body\">het samenwerken van landen in Europa na 1945.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Euro</div><div class=\"sam-definitie-body\">de gezamenlijke munt van veel EU-landen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vrij verkeer</div><div class=\"sam-definitie-body\">het vrij kunnen reizen, werken en handelen binnen de EU.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Globalisering</div><div class=\"sam-definitie-body\">het steeds meer verweven raken van landen wereldwijd.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vluchteling</div><div class=\"sam-definitie-body\">iemand die zijn land ontvlucht vanwege gevaar.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Migratie</div><div class=\"sam-definitie-body\">het verhuizen van mensen tussen landen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verdrag</div><div class=\"sam-definitie-body\">een officiële afspraak tussen landen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vrede</div><div class=\"sam-definitie-body\">het ontbreken van oorlog, een doel van Europese samenwerking.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Handel</div><div class=\"sam-definitie-body\">het kopen en verkopen tussen landen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Multinational</div><div class=\"sam-definitie-body\">een bedrijf dat in meerdere landen actief is.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Ontwikkelingshulp</div><div class=\"sam-definitie-body\">steun aan armere landen om zich te ontwikkelen.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Europese Unie»</b> is samenwerkende EU-landen, terwijl <b>«Europese samenwerking»</b> landen werken samen is. <b>«Euro»</b> is munt van de eurozone, terwijl <b>«Vrij verkeer»</b> vrij binnen de EU is. <b>«Vrij verkeer»</b> is vrij binnen de EU, terwijl <b>«Europese Unie»</b> samenwerkende EU-landen is. <b>«Globalisering»</b> is landen raken verweven, terwijl <b>«Handel»</b> kopen en verkopen is.</div>"}});